import org.junit.Assert;
import org.junit.Test;

/**
 * Test cases for the sparse iterator implementations.
 */
public class RealVectorSparseIteratorTest {

    /**
     * Minimal implementation of the {@link RealVector} abstract class.
     */
    public static class RealVectorTestImpl extends RealVector implements Serializable {

        /** Serializable version identifier. */
        private static final long serialVersionUID = 20240120L;

        /** Entries of the vector. */
        private final double[] data;

        /**
         * Build a vector with the given entries.
         * @param d vector entries
         */
        public RealVectorTestImpl(double[] d) {
            data = d.clone();
        }

        private UnsupportedOperationException unsupported() {
            return new UnsupportedOperationException("Not supported, unneeded for test purposes");
        }

        @Override
        public int getDimension() {
            return data.length;
        }

        @Override
        public double getEntry(int index) throws OutOfRangeException {
            checkIndex(index);
            return data[index];
        }

        @Override
        public void setEntry(int index, double value) throws OutOfRangeException {
            checkIndex(index);
            data[index] = value;
        }

        @Override
        public RealVector append(RealVector v) {
            throw unsupported();
        }

        @Override
        public RealVector append(double d) {
            throw unsupported();
        }

        @Override
        public RealVector getSubVector(int index, int n) {
            throw unsupported();
        }

        @Override
        public void setSubVector(int index, RealVector v) {
            throw unsupported();
        }

        @Override
        public boolean isNaN() {
            throw unsupported();
        }

        @Override
        public boolean isInfinite() {
            throw unsupported();
        }

        @Override
        public RealVector copy() {
            throw unsupported();
        }

        @Override
        public RealVector ebeDivide(RealVector v) {
            throw unsupported();
        }

        @Override
        public RealVector ebeMultiply(RealVector v) {
            throw unsupported();
        }
    }

    @Test
    public void testEmptyVectorHasNoNext() {
        double[] data = new double[0];
        RealVector v = new RealVectorTestImpl(data);
        Iterator<RealVector.Entry> iter = v.sparseIterator();
        Assert.assertFalse(iter.hasNext());
    }
}

