package org.apache.commons.math4.legacy.stat.descriptive.moment;

import org.junit.Assert;
import org.junit.Test;
import org.apache.commons.math4.legacy.stat.descriptive.moment.SemiVariance.Direction;

/**
 * Test cases for the {@link SemiVariance} class.
 */
public class SemiVarianceTest1 {

    /**
     * This test validates the default configuration and mutability of the SemiVariance
     * component's properties. It ensures that the variance direction and bias
     * correction properties are correctly initialized and can be modified.
     */
    @Test
    public void testSemiVarianceProperties() {
        SemiVariance semiVariance = new SemiVariance();

        // 1. Verify default variance direction
        Assert.assertEquals("Default variance direction should be DOWNSIDE",
                Direction.DOWNSIDE, semiVariance.getVarianceDirection());

        // 2. Modify and verify variance direction
        semiVariance.setVarianceDirection(Direction.UPSIDE);
        Assert.assertEquals("Variance direction should be updated to UPSIDE",
                Direction.UPSIDE, semiVariance.getVarianceDirection());

        // 3. Verify default bias correction
        Assert.assertTrue("Bias correction should be enabled by default",
                semiVariance.isBiasCorrected());

        // 4. Disable and verify bias correction
        semiVariance.setBiasCorrected(false);
        Assert.assertFalse("Bias correction should be disabled",
                semiVariance.isBiasCorrected());
    }
}

