package org.apache.commons.math4.legacy.stat.descriptive;

import org.apache.commons.math4.legacy.exception.MathIllegalArgumentException;
import org.junit.Test;
import org.junit.Assert;

public class StatisticsPercentileTest {

    @Test
    public void testPercentileEvaluation() {
        UnivariateStatistic percentile = Statistics.Percentile.create(50.0);

        // Verify that invoking the evaluate method with a null array triggers a null argument error
        try {
            percentile.evaluate(null);
            Assert.fail("Expected a MathIllegalArgumentException");
        } catch (MathIllegalArgumentException ex) {
            // Expected
        }

        // Confirm that evaluating an empty array returns NaN
        Assert.assertEquals(Double.NaN, percentile.evaluate(new double[0]), 0d);

        // Assert that a single-element array returns that element
        Assert.assertEquals(10.0, percentile.evaluate(new double[]{10.0}), 1e-9);

        // Verify that a two-element array produces the arithmetic mean
        Assert.assertEquals(15.0, percentile.evaluate(new double[]{10.0, 20.0}), 1e-9);

        // Validate that a three-element array correctly computes the median
        Assert.assertEquals(20.0, percentile.evaluate(new double[]{10.0, 20.0, 30.0}), 1e-9);
    }
}

package org.apache.commons.math4.legacy.stat.descriptive;

import org.apache.commons.math4.legacy.exception.MathIllegalArgumentException;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Tests for {@link DescriptiveStatistics} validation of percentile values.
 */
public class DescriptiveStatisticsPercentileTest {

    /**
     * This test validates that the percentile calculation system correctly rejects
     * invalid percentile values that fall outside the acceptable business range (0-100)
     * or are mathematically undefined (NaN).
     *
     * <p>It examines multiple problematic percentile values, including those below the
     * minimum threshold, above the maximum threshold, and NaN. For each invalid value,
     * it confirms that attempting to calculate the percentile results in a
     * {@link MathIllegalArgumentException}, indicating the value is out of the
     * acceptable range.
     *
     * <p>The test covers two scenarios as per the requirements:
     * <ol>
     *   <li>Attempting to calculate an invalid percentile after a valid one has already been computed.</li>
     *   <li>Attempting to calculate an invalid percentile on a fresh instance.</li>
     * </ol>
     * This ensures the validation logic is robust and not dependent on the object's prior state.
     *
     * @param invalidPercentile a value outside the accepted [0, 100] range to be tested.
     */
    @ParameterizedTest
    @ValueSource(doubles = {-10.0, 110.0, Double.NaN})
    void testInvalidPercentileValueIsRejected(double invalidPercentile) {
        // Scenario 1: Initialize with a valid percentile, then attempt to update to an invalid one.
        DescriptiveStatistics statsWithPriorState = new DescriptiveStatistics();
        statsWithPriorState.addValue(1.0);
        statsWithPriorState.addValue(2.0);
        // Establish a valid state by calculating a correct percentile first.
        Assertions.assertEquals(1.5, statsWithPriorState.getPercentile(50.0), 1e-9);

        // Verify that attempting to get an invalid percentile throws the expected exception.
        Assertions.assertThrows(MathIllegalArgumentException.class, () -> {
            statsWithPriorState.getPercentile(invalidPercentile);
        }, "Should have rejected percentile " + invalidPercentile + " after valid computation.");

        // Scenario 2: Attempt to initialize a fresh calculator directly with the invalid value.
        DescriptiveStatistics freshStats = new DescriptiveStatistics();
        freshStats.addValue(1.0);
        freshStats.addValue(2.0);

        // Verify that a fresh instance also rejects the invalid percentile.
        Assertions.assertThrows(MathIllegalArgumentException.class, () -> {
            freshStats.getPercentile(invalidPercentile);
        }, "Should have rejected percentile " + invalidPercentile + " on a fresh instance.");
    }
}

